            "sampleValue": "02:35"
          },
          "condition": {
            "type": "string",
            "description": "今日已服药顿数与计划总顿数。",
            "sampleValue": "2 / 4 顿"
          },
          "airQuality": {
            "type": "string",
            "description": "当前剩余药量百分比。",
            "sampleValue": "47%"
          }
        }
      }
    },
    "care": {
      "callLabel": {
        "type": "string",
        "description": "医生电话入口的短标签。",
        "sampleValue": "拨"
      },
      "doctorPhone": {
        "type": "string",
        "description": "用于拨号事件的医生联系电话样例。",
        "sampleValue": "13800138000"
      },
      "status": {
        "bloodPressure": {
          "type": "string",
          "description": "血压状态摘要。",
          "sampleValue": "偏高!"
        },
        "bloodSugar": {
          "type": "string",
          "description": "血糖状态摘要。",
          "sampleValue": "正常"
        },
        "heartRate": {
          "type": "string",
          "description": "心率状态摘要。",
          "sampleValue": "正常"
        }
      }
    }
  },
  "assetCandidates": []
}

